-- P7原Rush协议状态与冻结记录；未通过权威/原内容门禁不消费和发奖。
CREATE TABLE IF NOT EXISTS p7_rush_states (player_id BIGINT NOT NULL,day CHAR(10) NOT NULL,run_id BIGINT NOT NULL,floor INT NOT NULL,total_stars INT NOT NULL,record_stars INT NOT NULL,high_floor INT NOT NULL,free_reset_used INT NOT NULL,paid_reset_used INT NOT NULL,elite_used INT NOT NULL,elite_bought INT NOT NULL,addition_offer_section INT NOT NULL DEFAULT 0,active_fight VARBINARY(64) NOT NULL,PRIMARY KEY(player_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
